 entry={'ordinal':n,'goalId':e['goalId'],'wholeCurrentGoal':e['wholeGoal'],'path':str(asset),'assetPath':str(asset),'assetBinding':binding(asset),'sha256':binding(asset)['sha256'],'bytes':asset.stat().st_size,'dimensions':list(Image.open(asset).size),'provider':'built-in ChatGPT/Codex image_gen','tool':'image_gen__imagegen','model':None,'modelDisclosure':'Integrated tool does not expose model identifier.','originalPromptPath':e['originalPromptPath'],'originalPromptBinding':binding(e['originalPromptPath']),'actualGenerationProvenance':provenance,'reconstructionPromptPath':str(reconstructionPath),'reconstructionPromptBinding':binding(reconstructionPath),'reconstructionRole':'actual-view-derived; not original generator prompt','descriptionDe':description,'altTextDe':alt,'resourceLinkCandidate':resource,'actualAuthorInspection':{'originalSeen':True,'width360Seen':True,'width680Seen':True,'observations':observations,'previews':[binding(d/('candidate-v'+str(version)+'.preview-'+str(w)+'.png')) for w in (360,680)],'authority':'author inspection only; independent visualization reviews pending'},'status':'ai_candidate','humanApproval':False,'independentReviews':[],'activeIntegration':False}
